function updateLine2DSim() {
    const x = parseInt(document.getElementById('input-coord-x').value, 10);
    const y = parseInt(document.getElementById('input-coord-y').value, 10);

    document.getElementById('badge-coord-x').innerText = 'x = ' + x;
    document.getElementById('badge-coord-y').innerText = 'y = ' + y;

    const sum = 2 * x + y;
    document.getElementById('eval-val-2d').innerText = sum;
    document.getElementById('eval-calc-2d').innerText = `2(${x}) + (${y}) = ${sum}`;

    const box = document.getElementById('solution-2d-box');
    const title = document.getElementById('sol-2d-title');
    const desc = document.getElementById('sol-2d-desc');

    if (sum === 6) {
        box.style.background = 'rgba(16, 185, 129, 0.15)';
        box.style.borderColor = '#10b981';
        title.style.color = '#10b981';
        title.innerHTML = '<i class="fas fa-check-circle"></i> ON THE LINE!';
        desc.innerText = `(${x}, ${y}) satisfies 2x + y = 6. It is an ordered pair solution!`;
    } else {
        box.style.background = 'rgba(225, 29, 72, 0.15)';
        box.style.borderColor = '#f43f5e';
        title.style.color = '#f43f5e';
        title.innerHTML = '<i class="fas fa-times-circle"></i> NOT ON THE LINE';
        desc.innerText = `2(${x}) + (${y}) = ${sum} ≠ 6. Point does not satisfy equation.`;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    updateLine2DSim();
});
